const drawer=function(){return '<div class="drawer-screen" id="drawer-screen"><aside class="cart-drawer"><div class="drawer-head"><h3>Shopping Cart ('+cartQty()+')</h3><button class="drawer-close" id="drawer-close">×</button></div>'+(cart.length?cart.map(function(i){const p=product(i.id);return p?'<div class="drawer-item"><img src="'+productImage(p,180)+'" alt=""><span style="flex:1"><strong>'+esc(p.name)+'</strong><small>'+i.qty+' × '+money(p.price)+'</small></span><button class="drawer-close" data-remove="'+p.id+'">×</button></div>':''}).join('')+'<div class="summary-row total"><span>Subtotal</span><span>'+money(total())+'</span></div><a class="form-button" style="display:block;text-align:center;margin-top:14px" href="/checkout">Checkout</a><a class="text-link" style="display:block;text-align:center;margin-top:13px" href="/shopping-cart">Go to cart</a>':'<div class="empty-state"><div class="empty-icon">♧</div><h2>Your cart is empty</h2><a class="form-button" href="/shop-01">Shop now</a></div>')+'</aside></div>'};
const productCard=function(p){const wished=wishes.includes(p.id),available=Number(p.stockQty)>0,quantity=Number(p.stockQty).toLocaleString(undefined,{maximumFractionDigits:3});return '<article class="product-card"><span class="product-badge">'+(available?'Fresh':'Out of stock')+'</span><button class="wish-btn '+(wished?'active':'')+'" data-wish="'+p.id+'" aria-label="Add to wishlist">'+uiIcon('heart')+'</button><a class="product-thumb" href="/product-details?id='+encodeURIComponent(p.id)+'"><img loading="lazy" src="'+productImage(p,600)+'" alt="'+esc(p.name)+'"></a><div class="product-info"><div class="product-meta"><a class="product-cat" href="'+categoryHref([p.category,p.category,p.categoryCount,p.categoryId])+'">'+esc(p.category)+'</a><span class="product-stock">Qty: '+quantity+' '+esc(p.unit)+'</span></div><a href="/product-details?id='+encodeURIComponent(p.id)+'"><h3 class="product-name">'+esc(p.name)+'</h3></a><div class="stars">★★★★★<span style="color:#999;letter-spacing:0"> &nbsp;(5.0)</span></div><div class="product-price">'+money(p.price)+' <span style="color:#999;font-size:14px;font-weight:400">/ '+esc(p.unit)+'</span></div><div class="product-actions"><button class="add-cart" data-add="'+p.id+'" '+(available?'':'disabled')+'>'+(available?'＋ Add to Cart':'Out of Stock')+'</button><a class="quick-view" href="/product-details?id='+encodeURIComponent(p.id)+'" title="Quick view" aria-label="View product details">'+uiIcon('search')+'</a></div></div></article>'};
