const home=function(){return '<main><div class="container home-hero"><section class="hero-slider"><a href="/shop-01" aria-label="Shop Star Mart groceries"><img class="home-banner-image" src="/star-mart-home-banner.png" alt="Star Mart grocery store and mobile shopping"></a></section></div>'+'<section class="container section"><section class="container section">'+sectionHead('CATEGORY','Shop By Top Categories','View All →','shop-01','category-section-heading')+'<div class="category-cards">'+categoryCards()+'</div></section><section class="container section"><div class="section-heading"><div><div class="section-overline">PRODUCTS</div><h2>Our Featured Products</h2></div><a class="text-link" href="/shop-01">View All ?</a></div><div class="product-grid">'+products.slice(0,4).map(productCard).join('')+'</div></section><section class="container section">'+sectionHead('FRESH PICKS','Popular Products','Shop All →','shop-01')+'<div class="product-grid">'+products.slice(4,12).map(productCard).join('')+'</div></section><section class="container section">'+sectionHead('SHOPERY JOURNAL','Latest News & Articles','View All →','blog-list')+'<div class="blog-grid">'+blogCards()+'</div></section></main>'};
const crumb=function(title,trail,className){return '<div class="breadcrumb'+(className?' '+className:'')+'"><div class="container"><div class="crumbs"><a href="/">Home</a> &nbsp;›&nbsp; '+(trail||'')+' <strong>'+title+'</strong></div><div class="page-title">'+title+'</div></div></div>'};
const accountMenu=function(active){const name=esc(user&&user.name||'Dianne Russell');return '<aside class="panel account-menu"><div class="profile-summary"><img src="'+(user&&user.photo?esc(user.photo):img('photo-1500648767791-00dcc994a43e',180))+'" alt="Customer profile"><span>'+name+'</span><label class="profile-photo-change" for="profile-photo-input">Change picture<input id="profile-photo-input" type="file" accept="image/*" aria-label="Choose a new profile picture"></label><a class="edit-link" href="/account-setting">Edit Profile</a></div><nav><a class="'+(active==='dashboard'?'active':'')+'" href="/dashboard">'+uiIcon('dashboard')+' &nbsp;Dashboard</a><a class="'+(active==='orders'?'active':'')+'" href="/order-history">'+uiIcon('list')+' &nbsp;Order History</a><a class="'+(active==='wishlist'?'active':'')+'" href="/wishlist">'+uiIcon('heart')+' &nbsp;Wishlist</a><a class="'+(active==='cart'?'active':'')+'" href="/shopping-cart">'+uiIcon('cart')+' &nbsp;Shopping Cart</a><a class="'+(active==='settings'?'active':'')+'" href="/account-setting">'+uiIcon('settings')+' &nbsp;Settings</a><a href="/sign-in" data-logout>'+uiIcon('logout')+' &nbsp;Log out</a></nav></aside>'};
const shop=function(){const q=params();const cat=q.get('category')||'All Categories';const selectedCategory=cats.find(function(c){return c[0]===cat||c[3]===cat});const categoryName=selectedCategory?selectedCategory[0]:cat;const term=window.shopSearch||'';let list=products.filter(function(p){const goodCat=cat==='All Categories'||p.category===categoryName||p.categoryId===cat;const goodTerm=!term||(p.name+' '+p.category+' '+p.sku).toLowerCase().includes(term.toLowerCase());return goodCat&&goodTerm});if(window.shopSort==='low')list.sort(function(a,b){return a.price-b.price});if(window.shopSort==='high')list.sort(function(a,b){return b.price-a.price});return crumb(cat==='All Categories'?'Shop':categoryName,'Shop ›')+'<main class="container inner-page"><div class="account-layout"><aside class="panel category-sidebar" style="padding:19px;height:max-content"><h3 style="font-size:16px;font-weight:600;margin:0 0 12px">All Categories</h3>'+cats.map(function(c){return '<a href="'+categoryHref(c)+'" class="'+(c[0]===categoryName?'active':'')+'"><img src="'+esc(c[1])+'" alt="" loading="lazy"><span>'+esc(c[0])+'</span></a>'}).join('')+'<div style="margin-top:20px"><strong style="font-size:14px">Filter by price</strong><p style="font-size:14px;color:#888">Fresh groceries, selected for quality</p></div></aside><section><div class="panel-heading" style="padding:0 0 15px;border-bottom:1px solid #eee;margin-bottom:18px"><span style="font-size:14px;color:#777">Showing '+list.length+' products</span><select id="sort-select" class="field-input" style="padding:8px;border:1px solid #eee;border-radius:4px;font-size:14px"><option value="featured">Sort by: Featured</option><option value="low">Price: Low to High</option><option value="high">Price: High to Low</option></select></div><div class="product-grid">'+(list.length?list.map(productCard).join(''):'<div class="panel" style="padding:30px">No products found. Try another category or search.</div>')+'</div></section></div></main>'};
const productPage=function(){const p=product(params().get('id'));if(!p)return crumb('Product not found','Shop ›')+'<main class="container inner-page"><div class="panel empty-state"><h2>This product is no longer available.</h2><a class="form-button" href="/shop-01">Continue Shopping</a></div></main>';return crumb(p.name,'Shop › '+p.category+' ›')+'<main class="container inner-page"><div class="product-detail"><div class="detail-image"><img src="'+productImage(p,1000)+'" alt="'+esc(p.name)+'"></div><section class="detail-copy"><div class="product-cat">'+esc(p.category)+'</div><h1>'+esc(p.name)+'</h1><div class="stars">★★★★★ &nbsp;<span style="color:#888">Fresh from Star Mart</span></div><div class="detail-price">'+money(p.price)+'</div><p>'+esc(p.desc||'Freshly selected and carefully packed.')+'</p><p>✓ &nbsp;Freshly selected and carefully packed<br>✓ &nbsp;Delivered with freshness in mind<br>✓ &nbsp;30 day satisfaction guarantee</p><div class="detail-actions"><div class="qty"><button data-quantity="'+(p.allowFractional?-0.001:-1)+'">−</button><input id="product-qty" type="number" value="'+(p.allowFractional?Math.min(1,p.stockQty):1)+'" min="'+(p.allowFractional?0.001:1)+'" max="'+p.stockQty+'" step="'+(p.allowFractional?0.001:1)+'"><button data-quantity="'+(p.allowFractional?0.001:1)+'">+</button></div><button class="form-button" data-add="'+p.id+'" data-detail-add '+(Number(p.stockQty)>0?'':'disabled')+'>'+(Number(p.stockQty)>0?'Add to Cart':'Out of Stock')+'</button><button class="wish-btn '+(wishes.includes(p.id)?'active':'')+'" data-wish="'+p.id+'">♡</button></div><div style="font-size:14px;color:#888">Category: <a class="text-link" href="'+categoryHref([p.category,p.category,p.categoryCount,p.categoryId])+'">'+esc(p.category)+'</a></div></section></div><section class="section">'+sectionHead('YOU MAY ALSO LIKE','Related Products','','shop-01')+'<div class="product-grid">'+products.filter(function(x){return x.id!==p.id}).slice(0,4).map(productCard).join('')+'</div></section></main>'};
const ordersPanel=function(rows,limit){if(ordersLoading)return '<div class="panel empty-state"><p>Loading your orders...</p></div>';if(ordersError)return '<div class="panel empty-state" role="alert"><p>'+esc(ordersError)+'</p><button class="text-link" data-orders-retry>Try again</button></div>';if(!rows.length)return '<div class="panel empty-state"><h2>No orders yet</h2><p>Your completed checkouts will appear here.</p><a class="form-button" href="/shop-01">Start Shopping</a></div>';return '<div class="table-wrap"><table class="orders-table"><thead><tr><th>Order ID</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>'+rows.slice(0,limit||rows.length).map(function(o){return '<tr><td>#'+esc(o.number)+'</td><td>'+esc(o.date)+'</td><td><strong>'+money(o.total)+'</strong> ('+o.count+' products)</td><td><span class="status">'+esc(o.statusLabel)+'</span></td><td><a href="/order-details?id='+encodeURIComponent(o.id)+'">View Details</a></td></tr>'}).join('')+'</tbody></table></div>'};
const dashboard=function(){return '<main class="container inner-page"><div class="account-layout">'+accountMenu('dashboard')+'<div class="account-main"><section class="panel orders-panel"><div class="panel-heading"><h2>Recent Order History</h2><a class="edit-link" href="/order-history">View All</a></div>'+ordersPanel(orderRecords,5)+'</section></div></div></main>'};
const orderHistory=function(){return crumb('Order History','Account ›')+'<main class="container inner-page"><div class="account-layout">'+accountMenu('orders')+'<section class="panel orders-panel"><div class="panel-heading"><h2>Order History</h2><span style="font-size:14px;color:#888">'+(ordersLoading?'…':orderRecords.length)+' orders</span></div>'+ordersPanel(orderRecords)+'</section></div></main>'};
const cartItemsForDetails=function(){if(!selectedOrder||!selectedOrder.items||!selectedOrder.items.length)return '<tr><td colspan="4">No items were found for this order.</td></tr>';return selectedOrder.items.map(function(item){return '<tr><td><div class="cart-product"><img src="'+productImage({imageUrl:item.imageUrl},140)+'" alt=""><strong>'+esc(item.name)+'</strong></div></td><td>'+money(item.price)+'</td><td>'+esc(item.qty)+'</td><td>'+money(item.lineTotal)+'</td></tr>'}).join('')};
const orderDetails=function(){if(ordersLoading)return crumb('Order Details','Account › Order History ›')+'<main class="container inner-page"><div class="panel empty-state">Loading your order...</div></main>';if(ordersError||!selectedOrder)return crumb('Order Details','Account › Order History ›')+'<main class="container inner-page"><div class="panel empty-state" role="alert"><h2>'+esc(ordersError||'Order not found.')+'</h2><a class="form-button" href="/order-history">Back to Order History</a></div></main>';const status=selectedOrder.status;return crumb('Order Details','Account › Order History ›')+'<main class="container inner-page"><div class="account-layout">'+accountMenu('orders')+'<section class="panel" style="padding:22px"><div class="panel-heading" style="padding:0 0 16px"><h2>Order #'+esc(selectedOrder.number)+'</h2><span class="status">'+esc(selectedOrder.statusLabel)+'</span></div><div class="checkout-steps"><span class="active">Order placed</span><span class="'+(['confirmed','preparing','ready','out_for_delivery','completed'].includes(status)?'active':'')+'">Processing</span><span class="'+(['out_for_delivery','completed'].includes(status)?'active':'')+'">On the way</span><span class="'+(status==='completed'?'active':'')+'">Delivered</span></div><div class="table-wrap"><table class="cart-table"><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Subtotal</th></tr></thead><tbody>'+cartItemsForDetails()+'</tbody></table></div><div style="max-width:360px;margin:20px 0 0 auto"><div class="summary-row"><span>Subtotal</span><span>'+money(selectedOrder.subtotal)+'</span></div><div class="summary-row"><span>Shipping</span><span>'+money(selectedOrder.deliveryFee)+'</span></div><div class="summary-row total"><span>Total</span><span>'+money(selectedOrder.total)+'</span></div></div></section></div></main>'};
const cartPage=function(){if(!cart.length)return crumb('Shopping Cart','Shop ›')+'<main class="container inner-page"><div class="panel empty-state"><div class="empty-icon">♧</div><h2>Your cart is empty</h2><p>Fill your basket with fresh market favourites.</p><a class="form-button" href="/shop-01">Return to Shop</a></div></main>';return crumb('Shopping Cart','Shop ›')+'<main class="container inner-page two-col"><section class="panel"><div class="table-wrap"><table class="cart-table"><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Subtotal</th><th></th></tr></thead><tbody>'+cart.map(function(i){const p=product(i.id);return '<tr><td><div class="cart-product"><img src="'+productImage(p,150)+'" alt=""><strong>'+esc(p.name)+'</strong></div></td><td>'+money(p.price)+'</td><td><div class="qty"><button data-change="'+p.id+'" data-delta="'+(p.allowFractional?-0.001:-1)+'">−</button><input readonly value="'+i.qty+'"><button data-change="'+p.id+'" data-delta="'+(p.allowFractional?0.001:1)+'">+</button></div></td><td>'+money(p.price*i.qty)+'</td><td><button class="drawer-close" data-remove="'+p.id+'">×</button></td></tr>'}).join('')+'</tbody></table></div><div style="padding:14px"><a class="text-link" href="/shop-01">← Continue Shopping</a></div></section><aside class="panel summary-card"><h3>Cart Total</h3><div class="summary-row"><span>Subtotal</span><strong>'+money(total())+'</strong></div><div class="summary-row"><span>Shipping</span><strong>Calculated at checkout</strong></div><div class="summary-row total"><span>Total</span><span>'+money(total())+'</span></div><a class="form-button" style="display:block;text-align:center;margin-top:15px" href="/checkout">Proceed to Checkout</a></aside></main>'};
const checkout=function(){if(!cart.length)return crumb('Checkout','Shop ›')+'<main class="container inner-page"><div class="panel empty-state"><div class="empty-icon">♧</div><h2>Your cart is empty</h2><a class="form-button" href="/shop-01">Shop Now</a></div></main>';const initialFee=Number(deliverySettings.feePaisa)||0;const freeAbove=Number(deliverySettings.freeAbovePaisa);const shipping=Number.isFinite(freeAbove)&&freeAbove>0&&total()*100>=freeAbove?0:initialFee;return crumb('Checkout','Shop › Shopping Cart ›')+'<main class="container inner-page two-col"><form id="checkout-form" class="panel form-panel" style="max-width:none"><div class="checkout-steps"><span class="active">01 Billing Information</span><span>02 Shipping</span><span>03 Payment</span></div><h2>Contact Information</h2><div class="field-grid"><div class="field full"><label>Name</label><input required name="name" maxlength="120" readonly placeholder="Full name" value="'+esc(user&&user.name||'')+'"></div><div class="field full"><label>Email address</label><input required type="email" name="email" value="'+esc(user&&user.email||'')+'" readonly></div><div class="field"><label>Phone</label><input required name="phone" type="tel" maxlength="40" placeholder="Phone number"></div><div class="field full"><label>Fulfillment</label><label class="radio-line"><input type="radio" name="fulfillment" value="delivery" checked> Delivery</label><label class="radio-line"><input type="radio" name="fulfillment" value="pickup"> Store pickup</label></div><div class="field full" data-delivery-fields><label>Delivery address</label><input required name="address" maxlength="500" placeholder="House number, street, city, postal code"></div><div class="field full"><label>Order notes (optional)</label><textarea name="note" rows="3" maxlength="1000" placeholder="Notes about your order"></textarea></div></div><h2 style="margin-top:18px">Payment Method</h2><label class="radio-line"><input type="radio" name="payment" value="cash_on_delivery" checked> Cash on delivery</label><button class="form-button" style="width:100%;margin-top:12px">Place Order</button></form><aside class="panel summary-card"><h3>Order Summary</h3>'+cart.map(function(i){const p=product(i.id);return '<div class="summary-row"><span>'+esc(p.name)+' × '+i.qty+'</span><strong>'+money(p.price*i.qty)+'</strong></div>'}).join('')+'<div class="summary-row"><span>Shipping</span><strong id="checkout-shipping">'+money(shipping/100)+'</strong></div><div class="summary-row total"><span>Total</span><span>'+money(total()+shipping/100)+'</span></div><p style="font-size:14px;color:#999;line-height:1.6">Payment is collected on delivery. Product prices and stock are confirmed when you place the order.</p></aside></main>'};
const accountSettings=function(){return crumb('Account Settings','Account ›')+'<main class="container inner-page"><div class="account-layout">'+accountMenu('settings')+'<div class="account-main"><form class="panel form-panel" id="settings-form" style="max-width:none"><h2>Account Settings</h2><div class="field-grid"><div class="field"><label>Full name</label><input name="name" required value="'+esc(user&&user.name||'Dianne Russell')+'"></div><div class="field"><label>Email address</label><input name="email" type="email" required value="'+esc(user&&user.email||'dianne.russell@example.com')+'"></div><div class="field full"><label>Billing address</label><input name="address" value="'+esc(user&&user.address||'4140 Parker Rd. Allentown')+'"></div><div class="field"><label>Phone number</label><input value="(671) 555-0110"></div><div class="field"><label>Country</label><select><option>Pakistan</option><option>United States</option></select></div></div><button class="form-button">Save Changes</button></form></div></div></main>'};
const wishlistPage=function(){const list=products.filter(function(p){return wishes.includes(p.id)});return crumb('Wishlist','Account ›')+'<main class="container inner-page"><div class="account-layout">'+accountMenu('wishlist')+'<section>'+(list.length?'<div class="product-grid">'+list.map(productCard).join('')+'</div>':'<div class="panel empty-state"><div class="empty-icon">♡</div><h2>Your wishlist is empty</h2><p>Save products you love and find them here later.</p><a class="form-button" href="/shop-01">Explore Products</a></div>')+'</section></div></main>'};
const authVisual=function(){return '<aside class="auth-visual"><img src="'+img('photo-1542838132-92c53300491e',1000)+'" alt="Fresh produce selected for your table"><div class="auth-visual-shade"></div><div class="auth-visual-copy"><span>FRESH PICKS, EVERY DAY</span><h2>Good food starts with great choices.</h2><p>Discover fresh groceries and everyday essentials, thoughtfully selected for your home.</p><div class="auth-visual-points"><span>✓ Quality you can trust</span><span>✓ Everyday favorites in one place</span><span>✓ Easy, secure shopping</span></div></div></aside>'};
const signIn=function(){return crumb('Sign In','Account ›')+'<main class="auth-wrap"><div class="auth-layout">'+authVisual()+'<form class="auth-card" id="login-form"><div class="auth-brand"><img src="/star-mart-logo.png" alt="Star Mart"></div><h1>Welcome back</h1><p class="sub">Sign in to continue to your Star Mart account.</p><div class="field"><label>Email</label><input name="email" type="email" autocomplete="email" required placeholder="Email address"></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="current-password" required placeholder="Password"></div><div class="auth-options"><label class="checkline"><input type="checkbox"> Remember Me</label><a class="text-link" href="/forgot-password">Forget Password?</a></div><button class="form-button" style="width:100%">Sign In</button><div class="auth-foot">New to Star Mart? <a href="/create-account">Create an account</a></div></form></div></main>'};
const createAccount=function(){return crumb('Create Account','Account ›')+'<main class="auth-wrap"><div class="auth-layout">'+authVisual()+'<form class="auth-card" id="register-form"><div class="auth-brand"><img src="/star-mart-logo.png" alt="Star Mart"></div><h1>Create your account</h1><p class="sub">Join Star Mart for an easier way to shop.</p><div class="field"><label>Full name</label><input required name="name" autocomplete="name" placeholder="Your full name"></div><div class="field"><label>Email</label><input required name="email" type="email" autocomplete="email" placeholder="Email address"></div><div class="field"><label>Password</label><input required name="password" type="password" autocomplete="new-password" minlength="12" placeholder="At least 12 characters"></div><div class="field"><label>Confirm Password</label><input required name="confirm" type="password" autocomplete="new-password" minlength="12" placeholder="Confirm your password"></div><label class="checkline auth-terms"><input type="checkbox" required> I agree to the <a class="text-link" href="/terms">terms and conditions</a></label><button class="form-button" style="width:100%">Create Account</button><div class="auth-foot">Already have an account? <a href="/sign-in">Sign In</a></div></form></div></main>'};
const forgotPage=function(){return crumb('Forgot Password','Account ›')+'<main class="auth-wrap"><form class="auth-card" id="forgot-form"><h1>Forgot Password</h1><p class="sub">Enter your email to request a password reset.</p><div class="field"><label>Email</label><input name="email" type="email" required placeholder="Email address"></div><button class="form-button" style="width:100%">Send reset link</button><div class="auth-foot"><a href="/sign-in">Back to Sign In</a></div></form></main>'};
const faqPage=function(){const q=[['What areas do you deliver to?','We deliver to our current service areas. Enter your location during checkout to confirm availability.'],['How fresh are the products?','We select produce and everyday goods with care and pack them for your chosen delivery window.'],['Can I change an order after placing it?','Contact customer service as soon as possible. Changes depend on whether the order has already been packed.'],['What payment methods are available?','This demo shows cash on delivery and bank transfer options. Connect a payment provider to process real payments.'],['What if an item is missing or damaged?','Contact our support team with your order number and we will help arrange a suitable resolution.']];return crumb('Frequently Asked Questions','Help ›')+'<main class="container inner-page" style="max-width:850px">'+q.map(function(x,i){return '<div class="faq-item '+(i===0?'open':'')+'"><button class="faq-question" data-faq>'+x[0]+'<span>＋</span></button><div class="faq-answer">'+x[1]+'</div></div>'}).join('')+'</main>'};
const aboutPage=function(){return '<main class="about-page"><div class="container"><header class="about-page-heading"><span class="about-eyebrow">ABOUT STAR MART</span><h1>Fresh choices for everyday living</h1><p>Your neighborhood destination for fresh produce, pantry favorites, and the everyday essentials your home needs.</p></header><div class="about-layout"><aside class="about-visual"><img src="/star-mart-home-banner.png" alt="Fresh groceries and Star Mart shopping experience"><div class="about-visual-shade"></div><div class="about-visual-copy"><span class="about-visual-tag">FRESHNESS FOR EVERY DAY</span><h2>Good food brings us together.</h2><p>Explore a thoughtful selection of groceries for your table, your kitchen, and the moments you share.</p></div></aside><section class="panel about-story"><img class="about-logo" src="/star-mart-logo.png" alt="Star Mart logo"><span class="about-story-kicker">OUR STORY</span><h2>Welcome to Star Mart</h2><p>Star Mart makes it easy to shop for the groceries and household essentials you need. From fresh fruit and vegetables to pantry staples, discover everyday favorites in one convenient place.</p><p>We believe grocery shopping should feel simple and welcoming. Our goal is to help you find quality products for your home and make every visit to Star Mart a pleasant one.</p><div class="about-values"><div><span class="about-value-mark">✓</span><span><strong>Everyday essentials</strong><small>Groceries for your home and table</small></span></div><div><span class="about-value-mark">✓</span><span><strong>A simple shopping experience</strong><small>Find your favorites with ease</small></span></div><div><span class="about-value-mark">✓</span><span><strong>Here to help</strong><small>Our team is ready to assist</small></span></div></div><a class="form-button about-shop-button" href="/shop-01">Explore Star Mart <span aria-hidden="true">→</span></a></section></div></div></main>'};
const vendorPage=function(){return '<main class="vendor-page"><div class="container"><header class="vendor-page-heading"><span class="vendor-eyebrow">PARTNER WITH STAR MART</span><h1>Grow your business with us</h1><p>Bring your products to more local customers. Tell us about your business and our team will be in touch.</p></header><div class="vendor-layout"><aside class="vendor-visual"><img src="/star-mart-home-banner.png" alt="Fresh produce and groceries at Star Mart"><div class="vendor-visual-shade"></div><div class="vendor-visual-copy"><span class="vendor-visual-tag">A MARKETPLACE THAT GROWS WITH YOU</span><h2>Good things grow together.</h2><p>Showcase the products you are proud of and help local families discover something fresh.</p><div class="vendor-visual-note"><span class="vendor-note-icon">✓</span><span><strong>Let’s build something fresh</strong><small>Start your Star Mart partnership today</small></span></div></div></aside><section class="panel form-panel vendor-form-panel"><span class="vendor-form-kicker">VENDOR INQUIRY</span><h2>Tell us about your business</h2><p class="vendor-form-intro">Share a few details about your business and the products you would like to bring to our marketplace. This demo form does not submit information to a server.</p><form id="vendor-form"><div class="field-grid"><div class="field"><label>Business name</label><input name="business" required placeholder="Your business name"></div><div class="field"><label>Contact name</label><input name="name" required placeholder="Your name"></div><div class="field"><label>Email address</label><input name="email" type="email" required placeholder="you@example.com"></div><div class="field"><label>Product category</label><select name="category" required><option value="">Choose a category</option>'+cats.map(function(c){return '<option>'+esc(c[0])+'</option>'}).join('')+'</select></div><div class="field full"><label>Tell us about your products</label><textarea name="details" rows="4" required placeholder="What would you like to sell?"></textarea></div></div><button class="form-button vendor-submit">Send vendor inquiry <span aria-hidden="true">→</span></button></form></section></div></div></main>'};
const contactPage=function(){return crumb('Contact Us','Pages ›')+'<main class="container inner-page two-col"><section class="panel form-panel" style="max-width:none"><h2>Leave a Message</h2><form id="contact-form"><div class="field-grid"><div class="field"><label>Your name</label><input required placeholder="Name"></div><div class="field"><label>Email address</label><input required type="email" placeholder="Email"></div><div class="field full"><label>Subject</label><input required placeholder="How can we help?"></div><div class="field full"><label>Message</label><textarea required rows="5" placeholder="Write your message"></textarea></div></div><button class="form-button">Send Message</button></form></section><aside class="panel form-panel" style="max-width:none"><h2>Contact Information</h2><p style="font-size:14px;color:#777;line-height:1.8">Our customer support team is here to help with orders, delivery and product questions.</p><p style="font-size:14px;line-height:2">'+uiIcon('phone')+' &nbsp;+92 301 8681999<br>'+uiIcon('mail')+' &nbsp;support@starmartstore.com<br>'+uiIcon('pin')+' &nbsp;Star Villas, Bahawalpur<br>'+uiIcon('clock')+' &nbsp;Monday–Saturday, 9am–6pm</p><div style="height:180px;background:#eef7f2;display:grid;place-items:center;color:#556c63">Star Mart Location: Star Villas, Bahawalpur</div></aside></main>'};
const blogList=function(){return crumb('Blog List','Blog ›')+'<main class="container inner-page"><div class="blog-grid">'+blogCards()+blogCards()+'</div></main>'};
const singleBlog=function(){const a=articles[Number(params().get('id')||0)%articles.length];return crumb('Single Blog','Blog ›')+'<main class="container inner-page" style="max-width:850px"><img style="width:100%;height:370px;object-fit:cover;border-radius:5px" src="'+img(a.img,1200)+'"><div style="padding:20px 4px"><small class="section-overline">'+a.date+' · FOOD & LIFESTYLE</small><h1 style="font-size:28px;font-weight:600">'+a.title+'</h1><p style="font-size:14px;line-height:1.9;color:#777">'+a.text+' Shopery believes a thoughtful meal starts with simple, fresh ingredients. Explore the market for seasonal favourites and make them your own.</p><a href="/blog-list" class="text-link">← Back to blog</a></div></main>'};
const trackPage=function(){return crumb('Track Order','Account ›')+'<main class="container inner-page"><form class="panel form-panel" id="track-form"><h2>Track Your Order</h2><p style="font-size:14px;color:#888">Enter your order number and email address to view the latest delivery update.</p><div class="field-grid"><div class="field"><label>Order ID</label><input required placeholder="e.g. #738"></div><div class="field"><label>Email address</label><input type="email" required placeholder="Email address"></div></div><button class="form-button">Track Order</button><div id="track-result" style="display:none;margin-top:20px;padding:16px;background:#eef7f2;font-size:14px">Your order is being prepared. This is sample tracking information for the demo.</div></form></main>'};
const orderSuccess=function(){const id=params().get('id')||localStorage.getItem('shopery-last-order')||'SP-1001';return crumb('Order Placed','Checkout ›')+'<main class="container inner-page"><div class="panel empty-state"><div class="empty-icon">✓</div><h2>Thank you for your order!</h2><p>Your order reference is <strong>#'+esc(id)+'</strong>. You can follow updates from your dashboard.</p><a class="form-button" href="/order-history">View Order History</a></div></main>'};
const infoPage=function(title,body){return crumb(title,'Pages ›')+'<main class="container inner-page"><article class="panel info-content" style="padding:25px"><p>'+body+'</p><h2>Our commitment</h2><p>We aim to make shopping for fresh groceries straightforward and dependable. If you need help, our customer service team is ready to assist.</p></article></main>'};
const quickOrderActions=function(){return '<div class="quick-order-actions" aria-label="Quick order"><a class="quick-order-link quick-order-whatsapp" href="https://wa.me/923018681999?text=Hi%20Star%20Mart%2C%20I%27d%20like%20to%20place%20an%20order." target="_blank" rel="noopener noreferrer" aria-label="Chat with Star Mart on WhatsApp to place an order"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 11.7a8.5 8.5 0 0 1-12.6 7.4L3 20l.9-4.7a8.5 8.5 0 1 1 16.6-3.6Z"/><path d="M8.5 8.3c.2-.5.5-.5.8-.5h.5c.2 0 .4.1.5.4l.7 1.6c.1.2.1.4-.1.6l-.5.6c-.2.2-.2.4 0 .7.5.9 1.2 1.6 2.1 2.1.3.2.5.2.7 0l.7-.8c.2-.2.4-.2.6-.1l1.5.7c.3.1.4.3.4.5 0 .5-.3 1.4-.9 1.8-.6.4-1.3.6-2.1.4-1-.2-2.3-.8-3.7-2.1-1.1-1-1.8-2.3-2-3.2-.2-.9 0-1.8.5-2.5Z"/></svg><span><small>Quick chat</small><strong>WhatsApp order</strong></span></a></div>'};
const render=function(){const r=route(),catalogRoutes=['home','shop-01','shop-02','product-details','shopping-cart','checkout','wishlist'];if(user&&['dashboard','order-history','order-details'].includes(r))loadOrders();let body='';if(catalogRoutes.includes(r)&&!catalogLoaded)body='';else if(r==='home')body=home();else if(r==='shop-01'||r==='shop-02')body=shop();else if(r==='product-details')body=productPage();else if(r==='dashboard')body=dashboard();else if(r==='order-history')body=orderHistory();else if(r==='order-details')body=orderDetails();else if(r==='account-setting')body=accountSettings();else if(r==='shopping-cart')body=cartPage();else if(r==='checkout')body=checkout();else if(r==='wishlist')body=wishlistPage();else if(r==='sign-in')body=signIn();else if(r==='create-account')body=createAccount();else if(r==='forgot-password')body=forgotPage();else if(r==='faq')body=faqPage();else if(r==='about')body=aboutPage();else if(r==='contact')body=contactPage();else if(r==='become-a-vendor')body=vendorPage();else if(r==='blog-list')body=blogList();else if(r==='single-blog')body=singleBlog();else if(r==='track-order')body=trackPage();else if(r==='order-success')body=orderSuccess();else if(r==='terms')body=infoPage('Terms & Conditions','These demo terms describe a sample storefront only. Set your real store policies before accepting customer orders.');else if(r==='privacy')body=infoPage('Privacy Policy','This storefront stores your cart and preferences in this browser.');else body=crumb('Page Not Found','')+'<main class="container inner-page"><div class="panel empty-state"><div class="empty-icon">404</div><h2>Page not found</h2><a class="form-button" href="/">Back to home</a></div></main>';document.getElementById('app').innerHTML=header()+(catalogRoutes.includes(r)?catalogNotice():'')+body+(r==='home'&&catalogLoaded?quickOrderActions():'')+footer()+drawer();wire()};
const toast=function(message){let t=document.querySelector('.toast');if(!t){t=document.createElement('div');t.className='toast';document.body.appendChild(t)}t.textContent=message;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(function(){t.classList.remove('show')},2300)};
const addCart=function(id,qty){const p=product(id);if(!p){toast('This product is no longer available.');return}const requested=Number(qty);if(!Number.isFinite(requested)||requested<=0){toast('Enter a valid quantity.');return}const amount=p.allowFractional?Math.floor(requested*1000)/1000:Math.floor(requested);if(amount<=0){toast('Enter a valid quantity.');return}const line=cart.find(function(x){return String(x.id)===String(p.id)});const nextQty=p.allowFractional?Math.round(((line?line.qty:0)+amount)*1000)/1000:(line?line.qty:0)+amount;if(p.stockQty<=0||nextQty>p.stockQty){toast('Only '+p.stockQty+' '+p.unit+' available.');return}if(line)line.qty=nextQty;else cart.push({id:p.id,qty:amount});save();render();toast(p.name+' added to cart');const drawerScreen=document.getElementById('drawer-screen');if(drawerScreen)drawerScreen.classList.add('open')};
const changeQty=function(id,delta){const item=cart.find(function(x){return String(x.id)===String(id)}),p=product(id);if(!item||!p)return;const next=item.qty+delta;if(next<=0)cart=cart.filter(function(x){return String(x.id)!==String(id)});else if(next>p.stockQty)toast('Only '+p.stockQty+' '+p.unit+' available.');else{item.qty=p.allowFractional?next:Math.floor(next);if(item.qty<=0)cart=cart.filter(function(x){return String(x.id)!==String(id)})}save();render()};
const wire=function(){const profilePhotoInput=document.getElementById('profile-photo-input');if(profilePhotoInput)profilePhotoInput.addEventListener('change',function(){const file=profilePhotoInput.files&&profilePhotoInput.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Choose an image file');profilePhotoInput.value='';return}if(file.size>1500000){toast('Choose an image smaller than 1.5 MB');profilePhotoInput.value='';return}const reader=new FileReader();reader.onerror=function(){toast('Could not read this image. Please try another file.');profilePhotoInput.value=''};reader.onload=function(){if(typeof reader.result!=='string'){toast('Could not read this image. Please try another file.');profilePhotoInput.value='';return}const updatedUser=Object.assign({},user||{},{photo:reader.result});try{localStorage.setItem('shopery-user',JSON.stringify(updatedUser));user=updatedUser;render();toast('Profile picture updated')}catch(error){console.error('Unable to save the profile picture in this browser.',error);toast('Could not save the image. Choose a smaller file.');profilePhotoInput.value=''}};reader.readAsDataURL(file)});
document.querySelectorAll('[data-add]').forEach(function(button){button.addEventListener('click',function(){const input=document.getElementById('product-qty'),p=product(button.dataset.add),raw=input?Number(input.value):1,quantity=button.hasAttribute('data-detail-add')&&p&&p.allowFractional?raw:Math.max(1,Math.floor(raw||1));addCart(button.dataset.add,quantity)})});
document.querySelectorAll('[data-wish]').forEach(function(button){button.addEventListener('click',function(){const id=String(button.dataset.wish);if(wishes.includes(id))wishes=wishes.filter(function(value){return value!==id});else wishes.push(id);save();render();toast(wishes.includes(id)?'Added to wishlist':'Removed from wishlist')})});
document.querySelectorAll('[data-change]').forEach(function(button){button.addEventListener('click',function(){changeQty(button.dataset.change,Number(button.dataset.delta))})});
document.querySelectorAll('[data-remove]').forEach(function(button){button.addEventListener('click',function(){cart=cart.filter(function(item){return String(item.id)!==String(button.dataset.remove)});save();render()})});
const searchForm=document.getElementById('search-form');if(searchForm)searchForm.addEventListener('submit',function(event){event.preventDefault();window.shopSearch=document.getElementById('search-input').value.trim();nav('shop-01')});const allCategories=document.getElementById('all-categories');if(allCategories)allCategories.addEventListener('click',function(){nav('shop-01')});const mobileToggle=document.getElementById('mobile-toggle');if(mobileToggle)mobileToggle.addEventListener('click',function(){document.getElementById('nav-links').classList.toggle('mobile-open')});
document.querySelectorAll('[data-slide]').forEach(function(button){button.addEventListener('click',function(){slideIndex=Number(button.dataset.slide);document.querySelectorAll('.hero-slide').forEach(function(slide,index){slide.classList.toggle('active',index===slideIndex)});document.querySelectorAll('[data-slide]').forEach(function(dot,index){dot.classList.toggle('active',index===slideIndex)})})});const sort=document.getElementById('sort-select');if(sort){sort.value=window.shopSort||'featured';sort.addEventListener('change',function(){window.shopSort=sort.value;render()})}document.querySelectorAll('[data-quantity]').forEach(function(button){button.addEventListener('click',function(){const input=document.getElementById('product-qty'),p=product(params().get('id'));if(input&&p){const minimum=p.allowFractional?0.001:1,value=Math.round((Number(input.value)+Number(button.dataset.quantity))*1000)/1000;input.value=Math.max(minimum,Math.min(p.stockQty,value))}})});
document.querySelectorAll('[data-faq]').forEach(function(button){button.addEventListener('click',function(){button.parentElement.classList.toggle('open')})});document.querySelectorAll('.newsletter-form').forEach(function(form){form.addEventListener('submit',function(event){event.preventDefault();toast('Thanks for subscribing!');form.reset()})});const closeDrawer=document.getElementById('drawer-close');if(closeDrawer)closeDrawer.addEventListener('click',function(){document.getElementById('drawer-screen').classList.remove('open')});const drawerScreen=document.getElementById('drawer-screen');if(drawerScreen)drawerScreen.addEventListener('click',function(event){if(event.target===drawerScreen)drawerScreen.classList.remove('open')});
const settingsForm=document.getElementById('settings-form');if(settingsForm)settingsForm.addEventListener('submit',function(event){event.preventDefault();const values=new FormData(settingsForm);user=Object.assign({},user,{name:values.get('name'),address:values.get('address')});localStorage.setItem('shopery-user',JSON.stringify(user));render();toast('Profile saved in this browser')});
const checkoutForm=document.getElementById('checkout-form');if(checkoutForm){const fulfillmentFields=checkoutForm.querySelector('[data-delivery-fields]'),addressInput=checkoutForm.elements.address,shippingElement=document.getElementById('checkout-shipping'),grandTotalElement=checkoutForm.parentElement.querySelector('.summary-card .summary-row.total span:last-child');const refreshShipping=function(){const delivery=checkoutForm.elements.fulfillment.value==='delivery';if(fulfillmentFields){fulfillmentFields.hidden=!delivery;addressInput.required=delivery;addressInput.disabled=!delivery}const subtotal=total(),fee=delivery?Number(deliverySettings.feePaisa)||0:0,freeAbove=Number(deliverySettings.freeAbovePaisa);const shipping=delivery&&Number.isFinite(freeAbove)&&freeAbove>0&&subtotal*100>=freeAbove?0:fee;if(shippingElement)shippingElement.textContent=money(shipping/100);if(grandTotalElement)grandTotalElement.textContent=money(subtotal+shipping/100)};checkoutForm.addEventListener('change',refreshShipping);refreshShipping();checkoutForm.addEventListener('submit',async function(event){event.preventDefault();if(!checkoutRequestKey)checkoutRequestKey=window.crypto&&typeof window.crypto.randomUUID==='function'?window.crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/gu,function(c){const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)});const submitButton=checkoutForm.querySelector('button[type="submit"],button:not([type])'),originalText=submitButton?submitButton.textContent:'';if(submitButton){submitButton.disabled=true;submitButton.textContent='Placing order...'}try{const values=new FormData(checkoutForm),fulfillment=String(values.get('fulfillment')||'delivery'),address=[values.get('address')].map(function(value){return String(value||'').trim()}).filter(Boolean).join(', ');const response=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({items:cart.map(function(item){return{productId:item.id,qty:item.qty}}),fulfillment:fulfillment,deliveryAddress:fulfillment==='delivery'?address:'',phone:String(values.get('phone')||'').trim(),note:String(values.get('note')||'').trim(),requestKey:checkoutRequestKey})});const result=await response.json();if(!response.ok){toast(result.error||'We could not place your order. Please try again.');if(response.status===409)loadCatalog();return}cart=[];save();checkoutRequestKey='';orderLoadKey='';nav('order-success?id='+encodeURIComponent(result.number)+'&orderId='+encodeURIComponent(result.id))}catch(error){console.error('Storefront checkout request failed.',error);toast('We could not place your order. Please check your connection and try again.')}finally{if(submitButton){submitButton.disabled=false;submitButton.textContent=originalText}}})}
const forgotForm=document.getElementById('forgot-form');if(forgotForm)forgotForm.addEventListener('submit',function(event){event.preventDefault();toast('If the address is registered, reset instructions will be sent.')});const accountTrigger=document.querySelector('.account-trigger');if(accountTrigger)accountTrigger.addEventListener('click',function(){const open=accountTrigger.parentElement.classList.toggle('open');accountTrigger.setAttribute('aria-expanded',String(open))});const vendorForm=document.getElementById('vendor-form');if(vendorForm)vendorForm.addEventListener('submit',function(event){event.preventDefault();toast('Thanks for your interest. Vendor inquiries are a frontend demo only.');vendorForm.reset()});const contactForm=document.getElementById('contact-form');if(contactForm)contactForm.addEventListener('submit',function(event){event.preventDefault();toast('Thanks for contacting us.');contactForm.reset()});const trackForm=document.getElementById('track-form');if(trackForm)trackForm.addEventListener('submit',function(event){event.preventDefault();document.getElementById('track-result').style.display='block'});document.querySelectorAll('[data-orders-retry]').forEach(function(button){button.addEventListener('click',function(){orderLoadKey='';ordersError='';selectedOrder=null;loadOrders();render()})})};
window.addEventListener('shopery:auth-state',function(event){const sessionUser=event.detail;if(sessionUser&&typeof sessionUser.email==='string'){const saved=readStored('shopery-user',null);user=Object.assign({},sessionUser,saved&&saved.email===sessionUser.email?{photo:saved.photo,address:saved.address}:{});localStorage.setItem('shopery-user',JSON.stringify(user))}else{user=null;localStorage.removeItem('shopery-user');orderRecords=[];selectedOrder=null;orderLoadKey='';ordersLoading=false;ordersError=''}const protectedRoutes=['dashboard','order-history','order-details','account-setting','checkout'];if(!user&&protectedRoutes.includes(route())){nav('sign-in');return}render()});
window.addEventListener('shopery:auth-message',function(event){toast(String(event.detail||'Authentication failed'))});window.addEventListener('popstate',function(){render();window.scrollTo(0,0)});render();loadCatalog();